// UI texts in Spanish and English; entity names come from the legacy language files
// (packages/spec-data/generated/i18n, generated by `pnpm codegen`).
import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import es from "./es.json" with { type: "json" };
import en from "./en.json" with { type: "json" };
import esEntities from "@vendetta/spec-data/generated/i18n/es.json" with { type: "json" };
import enEntities from "@vendetta/spec-data/generated/i18n/en.json" with { type: "json" };

const stored = (() => {
  try {
    return localStorage.getItem("lang");
  } catch {
    return null;
  }
})();

void i18n.use(initReactI18next).init({
  resources: {
    es: { translation: { ...es, entities: esEntities } },
    en: { translation: { ...en, entities: enEntities } },
  },
  lng: stored ?? (navigator.language.startsWith("es") ? "es" : "en"),
  fallbackLng: "en",
  interpolation: { escapeValue: false },
});

i18n.on("languageChanged", (lng) => {
  document.documentElement.lang = lng;
  try {
    localStorage.setItem("lang", lng);
  } catch {
    /* private mode */
  }
});

export default i18n;
